//! SCSS lexer: reactive char-by-char `scan_map` transducer producing tokens.
//!
//! - `//` comments are dropped; `/* */` comments become [`Token::Comment`].
//! - `#{...}` inside words/strings folds into [`Token::Interpolated`] pieces.
//! - `url(...)` unquoted is consumed whole so `//` and `;` stay literal.
//! - `-` directly attached to a digit lexes as a negative number.
//!
//! Punctuation dispatch is generated by `#[derive(LexPunct)]` on [`Punct`]
//! (see `qrass-macros`); the per-state token scanners live in [`lexer_detail`].

use std::convert::Infallible;
use std::iter;

use rxrust::prelude::*;

use crate::error::{ErrorKind, Located, SassError};
use crate::span::{BytePos, FileId, Span};
use crate::token::{Punct, Spanned, Token};

pub(crate) type LxResult = Result<Spanned, SassError>;

// ─── Macros ────────────────────────────────────────────────────────────────────

/// Emit a spanned token ending at the current cursor: `emit!(self, token, start)`.
macro_rules! emit {
    ($self:expr, $tok:expr, $start:expr) => {
        Ok(Spanned {
            token: $tok,
            span: Span {
                file: $self.file,
                start: BytePos($start),
                end: BytePos($self.i),
            },
        })
    };
}

/// Build a located lex error at a char position: `lx_err!(self, "msg", at)`.
macro_rules! lx_err {
    ($self:expr, $msg:expr, $at:expr) => {{
        let (line, col) = $self.line_col($at);
        let excerpt = $self
            .cs
            .iter()
            .collect::<String>()
            .lines()
            .nth(line as usize - 1)
            .map(str::to_owned);
        SassError::new(ErrorKind::Lex, $msg).with_located(Located {
            file: $self.name.clone(),
            line,
            col,
            excerpt,
        })
    }};
}

// Per-state token scanners live in the sibling module; it uses the `spanned`/
// `err` helpers on `Lexer` (which expand the macros above) rather than the raw
// macros, so ordering here is irrelevant, but declaring it last keeps the
// macros textually in scope for the submodule too.
#[path = "lexer_detail.rs"]
mod lexer_detail;

// ─── Lexer state ───────────────────────────────────────────────────────────────

/// Accumulator for the reactive `scan_map` pipeline. Chars arrive one-by-one;
/// a token is emitted only once its boundary is confirmed by the following
/// character (or by EOF), so nothing is split prematurely.
pub struct Lexer {
    pub(crate) cs: Vec<char>,
    pub(crate) i: usize,
    pub(crate) len: usize,
    pub(crate) file: FileId,
    pub(crate) name: String,
    is_eof: bool,
    failed: bool,
    /// Set by a scanner whose decision needs a character that has not arrived
    /// yet (currently only `lex_hash`, which rewinds its cursor internally and
    /// would otherwise fake a confirmable boundary).
    provisional: bool,
}

impl Lexer {
    pub fn new(file: FileId, name: String) -> Self {
        Self {
            cs: Vec::new(),
            i: 0,
            len: 0,
            file,
            name,
            is_eof: false,
            failed: false,
            provisional: false,
        }
    }

    // ─── Reactive entry point (called by the scan_map closure) ─────────────

    /// Feed one char (`Some`) or EOF (`None`); returns 0..N confirmed tokens.
    pub fn feed(&mut self, ch: Option<char>) -> Vec<LxResult> {
        if self.failed {
            return Vec::new();
        }
        match ch {
            Some(c) => {
                self.cs.push(c);
                self.len += 1;
                self.try_emit()
            }
            None => {
                self.is_eof = true;
                self.try_emit()
            }
        }
    }

    /// Extract every token whose end boundary is confirmed by available data.
    ///
    /// During streaming a token is confirmable only when at least one character
    /// sits *after* it (`end + 1 < len`), so variable-width constructs — the `.`
    /// that may grow into `...`, or a number/unit that may extend — cannot be
    /// finalized while a continuation character has not arrived yet. An error
    /// before EOF is provisional (the closing delimiter of a comment/string may
    /// still be pending), so we rewind and wait rather than reporting it.
    fn try_emit(&mut self) -> Vec<LxResult> {
        let mut out = Vec::new();
        loop {
            if self.i >= self.len {
                break;
            }
            let saved = self.i;
            self.provisional = false;
            match self.next_token() {
                Some(Ok(s)) if !self.provisional && (self.is_eof || self.i + 1 < self.len) => {
                    out.push(Ok(s));
                }
                Some(Err(e)) if self.is_eof => {
                    self.failed = true;
                    out.push(Err(e));
                    break;
                }
                // Not confirmable yet (or error awaiting more input): rewind & wait.
                _ => {
                    self.i = saved;
                    break;
                }
            }
        }
        out
    }

    // ─── Tokenizer core ──────────────────────────────────────────────────────

    /// Produce the next token from the cursor, or `None` if only whitespace remains.
    pub fn next_token(&mut self) -> Option<LxResult> {
        while self.i < self.len && self.cs[self.i].is_whitespace() {
            self.i += 1;
        }
        if self.i >= self.len {
            return None;
        }
        let start = self.i;
        let ch = self.cs[self.i];
        let res = match ch {
            '/' if self.peek(1) == Some('/') => {
                while self.i < self.len && self.cs[self.i] != '\n' {
                    self.i += 1;
                }
                return self.next_token();
            }
            '/' if self.peek(1) == Some('*') => self.lex_block_comment(start),
            '"' | '\'' => self.lex_string(start),
            '@' => self.lex_at_keyword(start),
            '$' => self.lex_variable(start),
            '#' if self.peek(1) == Some('{') => self.lex_word(start),
            '#' => self.lex_hash(start),
            '%' if self.peek(1).is_some_and(is_ident_start) => self.lex_placeholder(start),
            '&' => {
                self.i += 1;
                emit!(self, Token::Ampersand, start)
            }
            '0'..='9' => self.lex_number(start),
            '.' if self.peek(1).is_some_and(|n| n.is_ascii_digit()) => self.lex_number(start),
            '-' if self.peek(1).is_some_and(|n| n.is_ascii_digit()) => self.lex_number(start),
            '-' if self.peek(1).is_some_and(|n| is_ident_start(n) || n == '-') => {
                self.lex_word(start)
            }
            c if is_ident_start(c) => self.lex_word(start),
            '.' if self.peek(1).is_some_and(is_ident_start) => self.lex_word(start),
            _ => self.lex_punct(start),
        };
        Some(res)
    }

    /// Fallback punct match, delegated to the generated `Punct::match_at`.
    fn lex_punct(&mut self, start: usize) -> LxResult {
        let ch = self.cs[start];
        let n1 = self.peek(1);
        let n2 = self.peek(2);
        match Punct::match_at(ch, n1, n2) {
            Some((punct, width)) => {
                self.i = start + width;
                emit!(self, Token::Punct(punct), start)
            }
            None => Err(self.err(format!("unexpected character '{ch}'"), start)),
        }
    }

    // ─── Utility ─────────────────────────────────────────────────────────────

    #[inline]
    pub(crate) fn peek(&self, ahead: usize) -> Option<char> {
        self.cs.get(self.i + ahead).copied()
    }

    pub(crate) fn line_col(&self, at: usize) -> (u32, u32) {
        let (mut line, mut col) = (1u32, 1u32);
        for &ch in &self.cs[..at.min(self.len)] {
            if ch == '\n' {
                line += 1;
                col = 1;
            } else if ch != '\r' {
                col += 1;
            }
        }
        (line, col)
    }

    #[inline]
    pub(crate) fn spanned(&self, token: Token, start: usize) -> LxResult {
        emit!(self, token, start)
    }

    pub(crate) fn err(&self, msg: impl Into<String>, at: usize) -> SassError {
        lx_err!(self, msg.into(), at)
    }
}

#[inline]
pub(crate) fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_' || (c as u32) >= 0x80
}

// ─── Public reactive API ─────────────────────────────────────────────────────

/// Token-level cold stream: chars flow one-by-one via `scan_map`; confirmed
/// tokens are emitted per step. Errors fuse (nothing further is emitted).
pub fn token_stream(
    file: FileId,
    name: String,
    content: String,
) -> LocalBoxedObservable<'static, LxResult, Infallible> {
    Local::from_iter(
        content
            .chars()
            .collect::<Vec<char>>()
            .into_iter()
            .map(Some)
            .chain(iter::once(None)),
    )
    .scan_map(Lexer::new(file, name), |lx, ch| lx.feed(ch))
    .filter(|batch| !batch.is_empty())
    .flat_map(|batch| Local::from_iter(batch))
    .box_it()
}

/// Synchronous convenience API for tests: lex an entire source into tokens.
pub fn lex(file: FileId, name: String, content: String) -> Result<Vec<Spanned>, SassError> {
    let mut lx = Lexer::new(file, name);
    let mut tokens = Vec::new();
    for ch in content.chars() {
        for r in lx.feed(Some(ch)) {
            match r {
                Ok(s) => tokens.push(s),
                Err(e) => return Err(e),
            }
        }
    }
    for r in lx.feed(None) {
        match r {
            Ok(s) => tokens.push(s),
            Err(e) => return Err(e),
        }
    }
    Ok(tokens)
}
